:0},"frames":{"type":"array","items":{"type":"object","required":["id","kind","source_ref","required","reason","placement"],"properties":{"id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"kind":{"enum":["room","image"],"type":"string"},"reason":{"type":"string","maxLength":2000,"minLength":1},"required":{"type":"boolean"},"placement":{"anyOf":[{"type":"object","required":["x","y","z","rx","ry","rz"],"properties":{"x":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"y":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"z":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"rx":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"ry":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"rz":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"}},"additionalProperties":false},{"type":"null"}]},"source_ref":{"type":"string"}},"additionalProperties":false},"maxItems":16,"description":"External-to-assembly transforms; every translation/rotation component names a parameter node. Room source_ref is parameter:<physical source node>; image source_ref is an exact opened image:<UUID>. Image camera directions and room compass axes are distinct. Null placement preserves unknown orientation/origin; required unknown transforms stop the request. Do not convert a reference image into measured truth. Local part, cut and view frames are supplied by the pinned engine convention."},"version":{"enum":[1],"type":"integer"},"bindings":{"type":"array","items":{"type":"object","required":["path","node"],"properties":{"node":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"path":{"type":"string","maxLength":240,"description":"Exact slash-separated recipe path through stable IDs and field names, as the recipe nests them; no dot notation or array positions. Bind every controlling numeric field; a position or rotation the recipe states as 0 may stay unbound, and code binds it to zero."}},"additionalProperties":false},"maxItems":8192,"minItems":0}},"additionalProperties":false},"form_refinement":{"anyOf":[{"type":"null"},{"type":"object","required":["version","mappings"],"properties":{"version":{"enum":[1],"type":"integer"},"mappings":{"type":"array","items":{"type":"object","required":["component_id","instance_ids"],"properties":{"component_id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_-]{0,31}$"},"instance_ids":{"type":"array","items":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"maxItems":128,"minItems":1,"uniqueItems":true}},"additionalProperties":false},"maxItems":48,"minItems":1}},"additionalProperties":false}]},"instance_policy":{"anyOf":[{"type":"null"},{"type":"object","required":["version","instances"],"properties":{"version":{"enum":[1],"type":"integer"},"instances":{"type":"array","items":{"anyOf":[{"type":"object","required":["instance_id","role","quantity_policy","reason"],"properties":{"role":{"enum":["build_part"],"type":"string"},"reason":{"type":"string","maxLength":2000,"minLength":1},"instance_id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"quantity_policy":{"enum":["manufacture"],"type":"string"}},"additionalProperties":false},{"type":"object","required":["instance_id","role","quantity_policy","reason"],"properties":{"role":{"enum":["existing_part"],"type":"string"},"reason":{"type":"string","maxLength":2000,"minLength":1},"instance_id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"quantity_policy":{"enum":["retain"],"type":"string"}},"additionalProperties":false},{"type":"object","required":["instance_id","role","quantity_policy","reason"],"properties":{"role":{"enum":["prefabricated_part"],"type":"string"},"reason":{"type":"string","maxLength":2000,"minLength":1},"instance_id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"quantity_policy":{"enum":["complete_item"],"type":"string"}},"additionalProperties":false},{"type":"object","required":["instance_id","role","quantity_policy","reason"],"properties":{"role":{"enum":["reference"],"type":"string"},"reason":{"type":"string","maxLength":2000,"minLength":1},"instance_id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"quantity_policy":{"enum":["exclude"],"type":"string"}},"additionalProperties":false},{"type":"object","required":["instance_id","role","quantity_policy","reason"],"properties":{"role":{"enum":["unknown"],"type":"string"},"reason":{"type":"string","maxLength":2000,"minLength":1},"instance_id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"quantity_policy":{"enum":["unknown"],"type":"string"}},"additionalProperties":false}]},"maxItems":512,"minItems":0}},"additionalProperties":false}]},"expected_revision":{"type":"integer","maximum":999999999,"minimum":0},"joint_rules":{"type":"array","maxItems":32,"description":"Your joining decision for two definitions: code writes one joint, with these fasteners and reason, for every pair of their parts that touch face to face and have no joint in joints. A pair of the same definition is [\"stud\",\"stud\"]. Touching parts that must not be joined this way go in except; they stay unjoined until you give them a joint. Empty for none.","items":{"type":"object","additionalProperties":false,"required":["id","between","reason","fasteners","except"],"properties":{"id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"between":{"type":"array","minItems":2,"maxItems":2,"items":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"}},"reason":{"type":"string","minLength":1,"maxLength":500},"fasteners":{"type":"array","maxItems":8,"description":"What holds this joint: catalog items with a fastener kind, in any mix; empty while nothing is chosen. count and spacing_mm follow how the item is counted: along the contact, a null count lets the database count and space it; per joint, give the count and no spacing; per construction, both stay null.","items":{"type":"object","additionalProperties":false,"required":["material_id","material_revision","count","spacing_mm"],"properties":{"material_id":{"type":"string","format":"uuid"},"material_revision":{"type":"integer","minimum":1,"maximum":999999999},"count":{"anyOf":[{"type":"integer","minimum":1,"maximum":10000},{"type":"null"}]},"spacing_mm":{"anyOf":[{"type":"number","exclusiveMinimum":0,"maximum":2000},{"type":"null"}]}}}},"except":{"type":"array","maxItems":64,"description":"Part id pairs this rule does not join, e.g. a part that rests, slides or is removable.","items":{"type":"array","minItems":2,"maxItems":2,"items":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"}}}}}}},"additionalProperties":false},"description":"Create or revise the requested construction concept after expert advice and significant choices are recorded in the selected solution for purpose=construction. Read its design_intent, investigate dependencies and recommend supported options before fixing geometry; reuse prior decisions and delegated technical choices. Canonical readiness is checked before compilation and again at save. You choose parts, joints and what holds them, and save this shared checkpoint; the saved result includes the whole-model check of that exact revision. A CAD drawing is not a substitute for this material/joint construction. Read current drafts and exact catalog materials first. Preserve stable IDs and unrelated parts. CAD parameter bindings compute dimensions and placements server-side in mm/deg. material_ref must be null; materials pins each definition. Joints name box faces in LOCAL part coordinates. Keep missing hardware/knowledge in open_questions. Correct issues reported by that check through the same construction. No strength, drawing or purchase approval is implied. For repeated identical parts use recipe.arrays (empty for none). Bind each array start and spacing in parameter_plan; the server expands stable <id>.1..<id>.<count> instances before normal compilation. Name expanded IDs in roles and joints. Arrays are authoring shorthand, not saved templates: later parameter/part changes target the saved expanded graph. For small changes use change_construction_parameters, change_construction_roles or edit_construction_parts. form_refinement:null uses the complete concept handoff. For an independent checkpoint, map selected concept component_ids to all actual instance_ids exactly once; one component may have several uncut, unrotated box parts within its exact envelope. Canonical component, parameter, feature, constraint and contacting-envelope dependencies determine whether unresolved choices affect this scope. All conceptual geometry still needs resolved supported values. Remaining components and choices stay visible on readback. An envelope is not proof of function: refinements remain unverified and cannot authorize drawings or purchases. Part edits keep the mapping in step with the parts. mode sketch builds a new construction in your sketch instead of saving it: send it in parts, every call with the same key, the current title, description, area and refinement, and the next parts; a definition, part, node, binding, material, joint or role with the same id replaces the earlier one. Each call is checked as a whole like a save and saves nothing. Save it once with commit_construction_sketch, new_key being that key. mode save saves at once. Lean writing: a number in the recipe may be a formula over parameter node names, with + - * / and parentheses and spaces around a minus sign; code adds its nodes and bindings, so bind by hand only fields written as numbers. joint_rules joins touching parts by definition pair; code writes those joints. Code completes form_refinement: a part no mapping names goes to the concept component whose envelope holds it, when exactly one does. A save refused only for a text, a formula or a joint rule is kept as a sketch under its key: send only the correction with mode sketch and the same key, then commit it.","expected_return":{"format":"json","contract":"The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt. A provider tool call alone is not a saved result."},"card_description":"Use when a new Construction must be authored, or an existing one revised as a whole, from the selected Solution's design intent. Gives a saved revision with parts, materials, joints and what holds them plus its whole-model check; small edits use change_construction_parameters or edit_construction_parts.","optional_parameters":[],"required_parameters":["key","record_id","expected_revision","title","description","area_id","change_note","recipe","parameter_plan","instance_policy","materials","joints","open_questions","request_quote","form_refinement","sub_build_id","mode","joint_rules"],"additional_description":"Read the selected Solution, its visible design_intent and current drafts and catalog revisions first. Resolve consequential geometry-dependent choices through expert advice and actual selections; reuse prior decisions and delegation. The server blocks construction save when canonical intent or supported controlling choices are missing. Preserve stable Artifact, assembly, part and joint IDs. Supply the complete CAD parameter plan; the server computes values and rejects unknown controlling dimensions. Open questions stay explicit. A draft receipt is not a drawing or purchase receipt. Derive spans and positions from shared dimension nodes. The saved result includes the check of that exact revision; correct reported IDs with another revision. Compare bounds and required features with the pinned Solution. A checked concept is not fabrication approval. For a drawing pass this checked construction Artifact ID to design_project_cad and verify the drawing save/link receipts and exact readback. instance_policy is subordinate to this exact construction revision: one saved instance ID per entry, version=1, with role/quantity_policy/reason. Allowed pairs: build_part/manufacture, existing_part/retain, prefabricated_part/complete_item, reference/exclude, unknown/unknown. Classify from evidence or an explicit design decision; never guess from a name. null preserves uncertainty and inherits only previously classified stable IDs. After saving a changed revision, read_construction_changes and complete the affected outputs before claiming delivery.\n\nThis shared construction is the required source for every project drawing. Preserve stable part IDs, explicit dimensions and placements, exact catalog material revisions and declared joint endpoints and fasteners. Compare the saved geometry with the owner requirements, reference image and stated coordinates before requesting CAD. The save result includes the check of the receipt revision; correct the same construction if needed. A single physical part may legitimately need no joint; do not invent one. Unknown material/joint evidence stays unknown and may prevent a drawing. For changes to existing parts, bindings, formulas, materials or joints, prefer edit_construction_parts: send only the changed posts and preserve the remainder server-side. Use change_construction_parameters for existing input values and change_construction_roles for roles. A full save is for creating a construction or an explicitly complete replacement, not a small correction. What holds each joint is your choice: find_catalog_materials finds what the catalog has, and add_catalog_fastener adds the hardware it lacks. The database measures each chosen item against the joint it holds and shows the facts per item in the construction check; where a fact speaks against an item, choose again or keep the joint open. A joint between two existing parts needs nothing new."}$lean_save$::jsonb,
    'tools.edit_construction_parts',$lean_edit${"name":"edit_construction_parts","handler":"edit_construction_parts","envelope":{"type":"function","arguments":"JSON object validated against parameters; project binding and write provenance remain server-owned.","schema_version":1},"parameters":{"type":"object","required":["key","record_id","expected_revision","change_note","request_quote","changes","solution_edit","text","mode","joint_rules","form_assign"],"properties":{"key":{"type":"string","pattern":"^[A-Za-z0-9_-]{1,80}$"},"mode":{"enum":["sketch","save"],"type":"string"},"text":{"anyOf":[{"type":"object","required":["title","description","open_questions"],"properties":{"title":{"type":"string","maxLength":200,"minLength":1},"description":{"type":"string","maxLength":5500,"minLength":1},"open_questions":{"anyOf":[{"type":"array","items":{"type":"string","maxLength":1000,"minLength":1},"maxItems":40},{"type":"null"}]}},"additionalProperties":false},{"type":"null"}]},"changes":{"type":"object","properties":{"nodes":{"type":"object","required":["upsert","remove"],"properties":{"remove":{"type":"array","items":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"maxItems":1024},"upsert":{"type":"array","items":{"anyOf":[{"type":"object","required":["id","role","source"],"properties":{"id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"},"role":{"enum":["source"],"type":"string"},"source":{"anyOf":[{"type":"object","required":["kind","id","revision"],"properties":{"id":{"type":"string","format":"uuid"},"kind":{"enum":["project_measurement"],"type":"string"},"revision":{"type":"integer","minimum":1}},"additionalProperties":false},{"type":"object","required":["kind","id","space_revision"],"properties":{"id":{"type":"string","format":"uuid"},"kind":{"enum":["space_measurement"],"type":"string"},"space_revision":{"type":"integer","minimum":1}},"additionalProperties":false}]}},"additionalProperties":false},{"type":"object","required":["id","role","va